document.addEventListener('DOMContentLoaded', function () {
  var configLinks = document.querySelectorAll('.config_lik_group a');
  if (configLinks.length > 0) {
    configLinks.forEach(function (link) {
      link.addEventListener('click', function (e) {
        setTimeout(function () {
          var headerNav = document.querySelector('.header-navigations');
          if (headerNav) {
            headerNav.scrollIntoView({
              behavior: 'smooth'
            });
          } else {
            console.error("Header navigation element not found");
          }
        }, 50);
      });
    });
  } else {
    console.warn("No configuration links found on this page");
  }

  // Responsive header - only initialize if header elements exist
  var contentHeader = document.querySelector('.content_header_bottom');
  console.log("ContentHeader", contentHeader);
  if (contentHeader) {
    var closeOtherMenus = function closeOtherMenus(currentMenu) {
      var allActiveMenus = contentHeader.querySelectorAll('.sous-menu.active');
      allActiveMenus.forEach(function (menu) {
        if (menu !== currentMenu) {
          var parentLi = menu.closest('.nav-item-custome');
          var caretBtn = parentLi ? parentLi.querySelector('.btn_caret') : null;
          var icon = caretBtn ? caretBtn.querySelector('i') : null;
          if (icon) {
            icon.classList.remove('fa-caret-up');
            icon.classList.add('fa-caret-down');
          }
          menu.classList.remove('active');
        }
      });
    };
    
    var sousMenuLinks = document.querySelectorAll('.sous-menu a');
    if (sousMenuLinks.length > 0) {
      sousMenuLinks.forEach(function (item) {
        item.addEventListener('click', function (e) {
          contentHeader.classList.remove('active');
          document.querySelector('html').classList.remove('no-scroll');
        });
      });
    }

    // accordeon mobile
    var btnCaret = contentHeader.querySelectorAll('.btn_caret');
    console.log("btnCaret", btnCaret.length);
    btnCaret.forEach(function (el) {
      el.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var parentLi = this.closest('.nav-item-custome');
        var sousMenu = parentLi ? parentLi.querySelector('.sous-menu') : null;
        console.log("Sous menu trouvé :", sousMenu);
        if (sousMenu) {
          if (sousMenu.classList.contains('active')) {
            sousMenu.classList.remove('active');
            var icon = this.querySelector('i');
            if (icon) {
              icon.classList.remove('fa-caret-up');
              icon.classList.add('fa-caret-down');
            }
          } else {
            closeOtherMenus(sousMenu);
            sousMenu.classList.add('active');
            var _icon = this.querySelector('i');
            if (_icon) {
              _icon.classList.remove('fa-caret-down');
              _icon.classList.add('fa-caret-up');
            }
          }
        }
      });
    });
    document.addEventListener('click', function (e) {
      if (!e.target.closest('.content_header_bottom') && !e.target.closest('.btn_toggle_header')) {
        contentHeader.classList.remove("active");
        document.querySelector('html').classList.remove('no-scroll');
      }
      if (!e.target.closest('.nav-item-custome')) {
        var allActiveMenus = contentHeader.querySelectorAll('.sous-menu.active');
        allActiveMenus.forEach(function (menu) {
          menu.classList.remove('active');
          var parentLi = menu.closest('.nav-item-custome');
          var caretBtn = parentLi ? parentLi.querySelector('.btn_caret') : null;
          var icon = caretBtn ? caretBtn.querySelector('i') : null;
          if (icon) {
            icon.classList.remove('fa-caret-up');
            icon.classList.add('fa-caret-down');
          }
        });
      }
    });
  } else {
    console.warn("Content header element not found, skipping header initialization");
  }
});

